window.MG_LAZY_DATA["data/lazy/courses/b170-9201da9c792da165.json"]={sha256:"9201da9c792da1655acfbee8135b14656237906e2712ff5d466a142e5ea9d171",value:{"id":"b170","title":"沉管水下對接與止水","titleEn":"Underwater immersed-tube joining and sealing","category":"underground","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"本課以沉管接頭幾何、壓縮接觸與雙重水密屏障為主線，從端面姿態與初始接觸與主密封壓縮與反力曲線建立系統邊界，再把溫度伸縮與軸向位移、剪力鍵承壓與接觸偏心連到屏障獨立性與交接檔案。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 十單元以可核算的模型和可追溯證據逐步判讀不同失效。","summaryEn":"This course focuses on immersed-joint geometry, compression contact and dual sealing barriers. It begins with End-face attitude and initial contact and Primary-seal compression and reaction curves, links Thermal expansion and axial movement and Shear-key bearing and eccentric contact, and ends with Barrier independence and handover records. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. Ten units use reproducible models and traceable evidence to distinguish failure mechanisms.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、開挖、注漿或受限空間作業許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, excavation, grouting or confined-space permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"ug-cutcover","subcategoryTitle":"明挖逆打與沉管","subcategoryTitleEn":"Cut-and-cover, top-down and immersed tunnels","learningTrack":"underground","learningSubdiscipline":"ug-cutcover","learningTags":["underground","ug-cutcover","immersed"],"architectureFamily":"immersed","architectureNodes":[["端面姿態與初始接觸","End-face attitude and initial contact"],["壓差合攏與受力邊界","Pressure-assisted closure and load boundaries"],["溫度伸縮與軸向位移","Thermal expansion and axial movement"],["剪力鍵承壓與接觸偏心","Shear-key bearing and eccentric contact"],["屏障獨立性與交接檔案","Barrier independence and handover records"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[0,3]],"diagram":{"type":"immersed","labels":["端面姿態與初始接觸","壓差合攏與受力邊界","溫度伸縮與軸向位移","剪力鍵承壓與接觸偏心","屏障獨立性與交接檔案"],"labelsEn":["End-face attitude and initial contact","Pressure-assisted closure and load boundaries","Thermal expansion and axial movement","Shear-key bearing and eccentric contact","Barrier independence and handover records"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"整合算例所有輸入均為教學假設。首先檢查端面姿態與初始接觸：differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm；再獨立檢查主密封壓縮與反力曲線：compressionRatio=closure/profileHeight=40 mm/100 mm=0.40。角差從 0.0005 增至 0.0008 rad，使 30 m 寬面上的幾何差由 15 增至 24 mm，增加六成；反力不一定同比。 兩個結果不能自動組成完整設計，因為接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 將同步記錄分區水壓、集水量及外水位變化作為模型以外的驗證證據，並保留原始紀錄與尚待確認的邊界。","textEn":"All inputs in this integrated example are teaching assumptions. First check End-face attitude and initial contact: differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm. Independently check Primary-seal compression and reaction curves: compressionRatio=closure/profileHeight=40 mm/100 mm=0.40. Increasing angular mismatch from 0.0005 to 0.0008 rad raises the differential across a 30 m face from 15 to 24 mm, a sixty-percent increase; reaction need not scale proportionally. The two results are not a complete design because joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. Use record compartment pressure, collected flow and external water-level changes together as evidence independent of the calculation, retaining raw records and unverified boundaries.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":14,"enrichmentVersion":14,"stages":[{"id":"b170-v14-s1","title":"地層條件、邊界與工程系統","titleEn":"Ground conditions, boundaries and engineering system","description":"本階段聚焦「端面姿態與初始接觸」與「主密封壓縮與反力曲線」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"End-face attitude and initial contact\" and \"Primary-seal compression and reaction curves\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b170-v14-01","title":"端面姿態與初始接觸：機制與系統路徑","titleEn":"End-face attitude and initial contact: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":[],"objective":"說明「端面姿態與初始接觸」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “End-face attitude and initial contact” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"接頭兩端面並非只需中心對準，偏航、俯仰和翹曲會使密封圈局部先接觸。第一接觸點承受的壓縮可能遠大於平均值，因而幾何差應沿整個周邊呈現；剛體角差模型只識別不均勻性，不能給出橡膠反力分布。 判別這個機制時，應觀察比較兩端面共同座標的周邊點雲與接觸順序；若出現中心線合格但端面角差使密封一側過壓而另一側未接觸，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「端面姿態與初始接觸」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Coincident centers do not ensure matching end faces: yaw, pitch and warping create early local seal contact. The first contact can compress far more than the average, so map mismatch around the perimeter. A rigid-angle model identifies nonuniformity but cannot determine rubber reaction distribution. Use the following check to discriminate the mechanism: Compare perimeter point clouds in common coordinates with the sequence of contact. If acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “End-face attitude and initial contact” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm.","failure":"常見誤解：「兩管節中心對準就代表周邊密封必定均勻接觸」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Aligned element centers guarantee uniform contact around the entire seal\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「端面姿態與初始接觸」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “End-face attitude and initial contact”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-01-k1","title":"端面姿態與初始接觸","titleEn":"End-face attitude and initial contact","text":"接頭兩端面並非只需中心對準，偏航、俯仰和翹曲會使密封圈局部先接觸。第一接觸點承受的壓縮可能遠大於平均值，因而幾何差應沿整個周邊呈現；剛體角差模型只識別不均勻性，不能給出橡膠反力分布。","textEn":"Coincident centers do not ensure matching end faces: yaw, pitch and warping create early local seal contact. The first contact can compress far more than the average, so map mismatch around the perimeter.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩管節中心對準就代表周邊密封必定均勻接觸 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Aligned element centers guarantee uniform contact around the entire seal Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「端面姿態與初始接觸」，下列哪一項敘述正確？","questionEn":"Which statement about \"End-face attitude and initial contact\" is correct?","options":["兩管節中心對準就代表周邊密封必定均勻接觸","接頭兩端面並非只需中心對準，偏航、俯仰和翹曲會使密封圈局部先接觸。","橡膠壓縮率相同就代表任何密封斷面的反力相同"],"optionsEn":["Aligned element centers guarantee uniform contact around the entire seal","Coincident centers do not ensure matching end faces: yaw, pitch and warping create early local seal contact.","Equal rubber compression ratios imply equal reaction for every seal profile"],"answer":1,"explanation":"接頭兩端面並非只需中心對準，偏航、俯仰和翹曲會使密封圈局部先接觸。 其餘選項是常見誤解。","explanationEn":"Coincident centers do not ensure matching end faces: yaw, pitch and warping create early local seal contact. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b170-v14-02","title":"端面姿態與初始接觸：定量估算","titleEn":"End-face attitude and initial contact: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-01"],"objective":"以數值模型估算「端面姿態與初始接觸」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “End-face attitude and initial contact” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：比較兩端面共同座標的周邊點雲與接觸順序。","observationEn":"How to cross-check: Compare perimeter point clouds in common coordinates with the sequence of contact.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「端面姿態與初始接觸」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"End-face attitude and initial contact\", which statement holds?","options":["壓力乘密封跨距即可直接得到所有位置的膜張力","量測接頭中央一個開度就能代表整圈密封變形","原創教學假設：differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm。"],"optionsEn":["Pressure times seal span directly gives membrane tension at every location","One central opening measurement represents deformation around the entire seal","Original teaching assumptions: differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm."],"answer":2,"explanation":"原創教學假設：differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm。 重算時請保留單位。","explanationEn":"Original teaching assumptions: differential=width*angle=30 m*0.0005 rad=0.015 m=15 mm. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b170-v14-03","title":"端面姿態與初始接觸：試驗與驗證","titleEn":"End-face attitude and initial contact: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「端面姿態與初始接觸」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “End-face attitude and initial contact” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"比較兩端面共同座標的周邊點雲與接觸順序。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「中心線合格但端面角差使密封一側過壓而另一側未接觸」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare perimeter point clouds in common coordinates with the sequence of contact. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將比較兩端面共同座標的周邊點雲與接觸順序列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現中心線合格但端面角差使密封一側過壓而另一側未接觸，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Compare perimeter point clouds in common coordinates with the sequence of contact. Link results to location, material batch and interpretation version. If acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：中心線合格但端面角差使密封一側過壓而另一側未接觸。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-03-k1","title":"驗證方法","titleEn":"Verification method","text":"比較兩端面共同座標的周邊點雲與接觸順序。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「中心線合格但端面角差使密封一側過壓而另一側未接觸」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Compare perimeter point clouds in common coordinates with the sequence of contact. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-03-k2","title":"現場實務","titleEn":"Site practice","text":"將比較兩端面共同座標的周邊點雲與接觸順序列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現中心線合格但端面角差使密封一側過壓而另一側未接觸，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Compare perimeter point clouds in common coordinates with the sequence of contact. Link results to location, material batch and interpretation version. If acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「端面姿態與初始接觸」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"End-face attitude and initial contact\"?","options":["比較兩端面共同座標的周邊點雲與接觸順序。","量測時不必記錄溫度、水頭、開挖序列與施工荷重，因為它們不會影響結果。","接頭集水少就能證明主次兩道密封都毫無缺陷"],"optionsEn":["Compare perimeter point clouds in common coordinates with the sequence of contact.","Temperature, water head, excavation sequence and construction loads need not be recorded because they cannot affect the result.","Low collected joint flow proves both primary and secondary seals are defect-free"],"answer":0,"explanation":"比較兩端面共同座標的周邊點雲與接觸順序。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare perimeter point clouds in common coordinates with the sequence of contact. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b170-v14-04","title":"端面姿態與初始接觸：失效診斷","titleEn":"End-face attitude and initial contact: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-03"],"objective":"從症狀倒推「端面姿態與初始接觸」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “End-face attitude and initial contact” and propose discriminating checks, corrective actions and prevention.","instruction":"中心線合格但端面角差使密封一側過壓而另一側未接觸。相似表徵也可能由量測偏差造成，因此應回到比較兩端面共同座標的周邊點雲與接觸順序，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other. Similar symptoms can arise from measurement bias: return to compare perimeter point clouds in common coordinates with the sequence of contact to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察比較兩端面共同座標的周邊點雲與接觸順序；若出現中心線合格但端面角差使密封一側過壓而另一側未接觸，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「兩管節中心對準就代表周邊密封必定均勻接觸」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Aligned element centers guarantee uniform contact around the entire seal\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-04-k1","title":"失效模式","titleEn":"Failure mode","text":"中心線合格但端面角差使密封一側過壓而另一側未接觸。相似表徵也可能由量測偏差造成，因此應回到比較兩端面共同座標的周邊點雲與接觸順序，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"Acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other. Similar symptoms can arise from measurement bias: return to compare perimeter point clouds in common coordinates with the sequence of contact to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「端面姿態與初始接觸」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"End-face attitude and initial contact\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","中心線合格但端面角差使密封一側過壓而另一側未接觸。","橡膠壓縮率相同就代表任何密封斷面的反力相同"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other.","Equal rubber compression ratios imply equal reaction for every seal profile"],"answer":1,"explanation":"中心線合格但端面角差使密封一側過壓而另一側未接觸。 需以量測區分可能原因。","explanationEn":"Acceptable centerline alignment conceals excessive compression on one seal side and a gap on the other. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b170-v14-05","title":"主密封壓縮與反力曲線：機制與系統路徑","titleEn":"Primary-seal compression and reaction curves: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-04"],"objective":"說明「主密封壓縮與反力曲線」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Primary-seal compression and reaction curves” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"Gina 類主密封利用端面壓縮建立接觸，但空心斷面與材料非線性使反力不會簡單正比壓縮率。製造商試驗曲線應對應實際斷面和溫度，接縫、轉角及長期鬆弛另行評估；幾何壓縮率只能作版本與尺寸核對。 判別這個機制時，應觀察將周邊壓縮量與相符斷面試驗曲線及材料批次比對；若出現借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「主密封壓縮與反力曲線」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A Gina-type primary seal develops contact through end compression, but hollow geometry and nonlinear rubber prevent reaction from scaling directly with compression ratio. Match manufacturer tests to the profile and temperature and assess corners, splices and relaxation separately. A geometric ratio checks dimensions and configuration only. Use the following check to discriminate the mechanism: Compare perimeter compression with matching profile tests and material batches. If using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Primary-seal compression and reaction curves” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：compressionRatio=closure/profileHeight=40 mm/100 mm=0.40。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: compressionRatio=closure/profileHeight=40 mm/100 mm=0.40.","failure":"常見誤解：「橡膠壓縮率相同就代表任何密封斷面的反力相同」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal rubber compression ratios imply equal reaction for every seal profile\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「主密封壓縮與反力曲線」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Primary-seal compression and reaction curves”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-05-k1","title":"主密封壓縮與反力曲線","titleEn":"Primary-seal compression and reaction curves","text":"Gina 類主密封利用端面壓縮建立接觸，但空心斷面與材料非線性使反力不會簡單正比壓縮率。製造商試驗曲線應對應實際斷面和溫度，接縫、轉角及長期鬆弛另行評估；幾何壓縮率只能作版本與尺寸核對。","textEn":"A Gina-type primary seal develops contact through end compression, but hollow geometry and nonlinear rubber prevent reaction from scaling directly with compression ratio. Match manufacturer tests to the profile and temperature and assess corners, splices and relaxation separately.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：橡膠壓縮率相同就代表任何密封斷面的反力相同 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal rubber compression ratios imply equal reaction for every seal profile Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「主密封壓縮與反力曲線」，下列哪一項敘述正確？","questionEn":"Which statement about \"Primary-seal compression and reaction curves\" is correct?","options":["橡膠壓縮率相同就代表任何密封斷面的反力相同","外水壓乘全部濕表面就等於接頭軸向合攏力","Gina 類主密封利用端面壓縮建立接觸，但空心斷面與材料非線性使反力不會簡單正比壓縮率。"],"optionsEn":["Equal rubber compression ratios imply equal reaction for every seal profile","External pressure times every wet surface equals the axial joint-closing force","A Gina-type primary seal develops contact through end compression, but hollow geometry and nonlinear rubber prevent reaction from scaling directly with compression ratio."],"answer":2,"explanation":"Gina 類主密封利用端面壓縮建立接觸，但空心斷面與材料非線性使反力不會簡單正比壓縮率。 其餘選項是常見誤解。","explanationEn":"A Gina-type primary seal develops contact through end compression, but hollow geometry and nonlinear rubber prevent reaction from scaling directly with compression ratio. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b170-v14-06","title":"主密封壓縮與反力曲線：定量估算","titleEn":"Primary-seal compression and reaction curves: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-05"],"objective":"以數值模型估算「主密封壓縮與反力曲線」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Primary-seal compression and reaction curves” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：compressionRatio=closure/profileHeight=40 mm/100 mm=0.40。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: compressionRatio=closure/profileHeight=40 mm/100 mm=0.40. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將周邊壓縮量與相符斷面試驗曲線及材料批次比對。","observationEn":"How to cross-check: Compare perimeter compression with matching profile tests and material batches.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：compressionRatio=closure/profileHeight=40 mm/100 mm=0.40。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: compressionRatio=closure/profileHeight=40 mm/100 mm=0.40. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「主密封壓縮與反力曲線」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Primary-seal compression and reaction curves\", which statement holds?","options":["原創教學假設：compressionRatio=closure/profileHeight=40 mm/100 mm=0.40。","長管節的自由熱伸縮必定全部集中在單一接頭","剪力鍵外觀面積全部都會同時均勻承受剪力"],"optionsEn":["Original teaching assumptions: compressionRatio=closure/profileHeight=40 mm/100 mm=0.40.","All free thermal expansion of a long element concentrates at one joint","The full visible shear-key area always carries shear uniformly"],"answer":0,"explanation":"原創教學假設：compressionRatio=closure/profileHeight=40 mm/100 mm=0.40。 重算時請保留單位。","explanationEn":"Original teaching assumptions: compressionRatio=closure/profileHeight=40 mm/100 mm=0.40. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b170-v14-07","title":"主密封壓縮與反力曲線：試驗與驗證","titleEn":"Primary-seal compression and reaction curves: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「主密封壓縮與反力曲線」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Primary-seal compression and reaction curves” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將周邊壓縮量與相符斷面試驗曲線及材料批次比對。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare perimeter compression with matching profile tests and material batches. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將將周邊壓縮量與相符斷面試驗曲線及材料批次比對列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Compare perimeter compression with matching profile tests and material batches. Link results to location, material batch and interpretation version. If using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-07-k1","title":"驗證方法","titleEn":"Verification method","text":"將周邊壓縮量與相符斷面試驗曲線及材料批次比對。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Compare perimeter compression with matching profile tests and material batches. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-07-k2","title":"現場實務","titleEn":"Site practice","text":"將將周邊壓縮量與相符斷面試驗曲線及材料批次比對列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Compare perimeter compression with matching profile tests and material batches. Link results to location, material batch and interpretation version. If using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「主密封壓縮與反力曲線」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Primary-seal compression and reaction curves\"?","options":["沿用另一條隧道或另一處地層的量測結果，就可視為本工程已完成驗證。","將周邊壓縮量與相符斷面試驗曲線及材料批次比對。","壓縮量固定就表示橡膠密封反力永遠不會降低"],"optionsEn":["Reusing results from another tunnel or ground formation counts as verifying this structure.","Compare perimeter compression with matching profile tests and material batches.","Fixed compression means rubber sealing reaction never decreases over time"],"answer":1,"explanation":"將周邊壓縮量與相符斷面試驗曲線及材料批次比對。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare perimeter compression with matching profile tests and material batches. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b170-v14-08","title":"主密封壓縮與反力曲線：失效診斷","titleEn":"Primary-seal compression and reaction curves: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-07"],"objective":"從症狀倒推「主密封壓縮與反力曲線」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Primary-seal compression and reaction curves” and propose discriminating checks, corrective actions and prevention.","instruction":"借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力。相似表徵也可能由量測偏差造成，因此應回到將周邊壓縮量與相符斷面試驗曲線及材料批次比對，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity. Similar symptoms can arise from measurement bias: return to compare perimeter compression with matching profile tests and material batches to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察將周邊壓縮量與相符斷面試驗曲線及材料批次比對；若出現借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「橡膠壓縮率相同就代表任何密封斷面的反力相同」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal rubber compression ratios imply equal reaction for every seal profile\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-08-k1","title":"失效模式","titleEn":"Failure mode","text":"借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力。相似表徵也可能由量測偏差造成，因此應回到將周邊壓縮量與相符斷面試驗曲線及材料批次比對，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"Using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity. Similar symptoms can arise from measurement bias: return to compare perimeter compression with matching profile tests and material batches to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「主密封壓縮與反力曲線」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Primary-seal compression and reaction curves\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","外水壓乘全部濕表面就等於接頭軸向合攏力","借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","External pressure times every wet surface equals the axial joint-closing force","Using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity."],"answer":2,"explanation":"借用不同斷面曲線高估接觸反力，局部水壓超過有效密封能力。 需以量測區分可能原因。","explanationEn":"Using another profile curve overstates contact reaction and leaves local water pressure beyond effective sealing capacity. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b170-v14-s2","title":"機制、材料與定量設計","titleEn":"Mechanisms, materials and quantitative design","description":"本階段聚焦「壓差合攏與受力邊界」與「次級密封與膜面荷載」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Pressure-assisted closure and load boundaries\" and \"Secondary seals and membrane loading\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b170-v14-09","title":"壓差合攏與受力邊界：機制與系統路徑","titleEn":"Pressure-assisted closure and load boundaries: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-08"],"objective":"說明「壓差合攏與受力邊界」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Pressure-assisted closure and load boundaries” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"接合階段內外壓差對封閉投影面產生軸向合力，經管節、接頭與支承形成平衡。計算面積應是壓差實際作用的有效面，不能混用水下面積或密封橡膠面積；摩擦、姿態和臨時構造使實際位移不能只由壓力推得。 判別這個機制時，應觀察對照壓力分區圖、端面位移與接頭受力路徑；若出現漏列與外水連通的腔室，錯算有效壓差及合攏力，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「壓差合攏與受力邊界」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"During joining, pressure difference over a closed projected area produces axial force balanced through the element, joint and supports. Use the actual pressure-boundary area rather than submerged surface or rubber contact area. Friction, attitude and temporary works prevent pressure alone from predicting displacement. Use the following check to discriminate the mechanism: Compare pressure-zone diagrams, end-face displacement and joint load paths. If an omitted chamber connected to external water produces the wrong pressure difference and closure force, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Pressure-assisted closure and load boundaries” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN.","failure":"常見誤解：「外水壓乘全部濕表面就等於接頭軸向合攏力」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"External pressure times every wet surface equals the axial joint-closing force\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「壓差合攏與受力邊界」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Pressure-assisted closure and load boundaries”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-09-k1","title":"壓差合攏與受力邊界","titleEn":"Pressure-assisted closure and load boundaries","text":"接合階段內外壓差對封閉投影面產生軸向合力，經管節、接頭與支承形成平衡。計算面積應是壓差實際作用的有效面，不能混用水下面積或密封橡膠面積；摩擦、姿態和臨時構造使實際位移不能只由壓力推得。","textEn":"During joining, pressure difference over a closed projected area produces axial force balanced through the element, joint and supports. Use the actual pressure-boundary area rather than submerged surface or rubber contact area.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：外水壓乘全部濕表面就等於接頭軸向合攏力 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: External pressure times every wet surface equals the axial joint-closing force Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「壓差合攏與受力邊界」，下列哪一項敘述正確？","questionEn":"Which statement about \"Pressure-assisted closure and load boundaries\" is correct?","options":["接合階段內外壓差對封閉投影面產生軸向合力，經管節、接頭與支承形成平衡。","外水壓乘全部濕表面就等於接頭軸向合攏力","壓力乘密封跨距即可直接得到所有位置的膜張力"],"optionsEn":["During joining, pressure difference over a closed projected area produces axial force balanced through the element, joint and supports.","External pressure times every wet surface equals the axial joint-closing force","Pressure times seal span directly gives membrane tension at every location"],"answer":0,"explanation":"接合階段內外壓差對封閉投影面產生軸向合力，經管節、接頭與支承形成平衡。 其餘選項是常見誤解。","explanationEn":"During joining, pressure difference over a closed projected area produces axial force balanced through the element, joint and supports. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b170-v14-10","title":"壓差合攏與受力邊界：定量估算","titleEn":"Pressure-assisted closure and load boundaries: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-09"],"objective":"以數值模型估算「壓差合攏與受力邊界」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Pressure-assisted closure and load boundaries” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：對照壓力分區圖、端面位移與接頭受力路徑。","observationEn":"How to cross-check: Compare pressure-zone diagrams, end-face displacement and joint load paths.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「壓差合攏與受力邊界」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Pressure-assisted closure and load boundaries\", which statement holds?","options":["量測接頭中央一個開度就能代表整圈密封變形","原創教學假設：axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN。","接頭集水少就能證明主次兩道密封都毫無缺陷"],"optionsEn":["One central opening measurement represents deformation around the entire seal","Original teaching assumptions: axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN.","Low collected joint flow proves both primary and secondary seals are defect-free"],"answer":1,"explanation":"原創教學假設：axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN。 重算時請保留單位。","explanationEn":"Original teaching assumptions: axialResultant=dp*effectiveArea=0.20 MPa*100 m2=20 MN. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b170-v14-11","title":"壓差合攏與受力邊界：試驗與驗證","titleEn":"Pressure-assisted closure and load boundaries: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「壓差合攏與受力邊界」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Pressure-assisted closure and load boundaries” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"對照壓力分區圖、端面位移與接頭受力路徑。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「漏列與外水連通的腔室，錯算有效壓差及合攏力」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare pressure-zone diagrams, end-face displacement and joint load paths. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: An omitted chamber connected to external water produces the wrong pressure difference and closure force. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將對照壓力分區圖、端面位移與接頭受力路徑列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現漏列與外水連通的腔室，錯算有效壓差及合攏力，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Compare pressure-zone diagrams, end-face displacement and joint load paths. Link results to location, material batch and interpretation version. If an omitted chamber connected to external water produces the wrong pressure difference and closure force, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：漏列與外水連通的腔室，錯算有效壓差及合攏力。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: An omitted chamber connected to external water produces the wrong pressure difference and closure force. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-11-k1","title":"驗證方法","titleEn":"Verification method","text":"對照壓力分區圖、端面位移與接頭受力路徑。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「漏列與外水連通的腔室，錯算有效壓差及合攏力」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Compare pressure-zone diagrams, end-face displacement and joint load paths. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: An omitted chamber connected to external water produces the wrong pressure difference and closure force. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-11-k2","title":"現場實務","titleEn":"Site practice","text":"將對照壓力分區圖、端面位移與接頭受力路徑列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現漏列與外水連通的腔室，錯算有效壓差及合攏力，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Compare pressure-zone diagrams, end-face displacement and joint load paths. Link results to location, material batch and interpretation version. If an omitted chamber connected to external water produces the wrong pressure difference and closure force, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「壓差合攏與受力邊界」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Pressure-assisted closure and load boundaries\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","只要安裝兩道密封就必定得到完全獨立的雙重保障","對照壓力分區圖、端面位移與接頭受力路徑。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Installing two seals always creates completely independent redundant protection","Compare pressure-zone diagrams, end-face displacement and joint load paths."],"answer":2,"explanation":"對照壓力分區圖、端面位移與接頭受力路徑。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare pressure-zone diagrams, end-face displacement and joint load paths. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b170-v14-12","title":"壓差合攏與受力邊界：失效診斷","titleEn":"Pressure-assisted closure and load boundaries: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-11"],"objective":"從症狀倒推「壓差合攏與受力邊界」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Pressure-assisted closure and load boundaries” and propose discriminating checks, corrective actions and prevention.","instruction":"漏列與外水連通的腔室，錯算有效壓差及合攏力。相似表徵也可能由量測偏差造成，因此應回到對照壓力分區圖、端面位移與接頭受力路徑，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"An omitted chamber connected to external water produces the wrong pressure difference and closure force. Similar symptoms can arise from measurement bias: return to compare pressure-zone diagrams, end-face displacement and joint load paths to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察對照壓力分區圖、端面位移與接頭受力路徑；若出現漏列與外水連通的腔室，錯算有效壓差及合攏力，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If an omitted chamber connected to external water produces the wrong pressure difference and closure force, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「外水壓乘全部濕表面就等於接頭軸向合攏力」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"External pressure times every wet surface equals the axial joint-closing force\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-12-k1","title":"失效模式","titleEn":"Failure mode","text":"漏列與外水連通的腔室，錯算有效壓差及合攏力。相似表徵也可能由量測偏差造成，因此應回到對照壓力分區圖、端面位移與接頭受力路徑，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"An omitted chamber connected to external water produces the wrong pressure difference and closure force. Similar symptoms can arise from measurement bias: return to compare pressure-zone diagrams, end-face displacement and joint load paths to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「壓差合攏與受力邊界」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Pressure-assisted closure and load boundaries\" shows distress, which diagnosis is most reasonable?","options":["漏列與外水連通的腔室，錯算有效壓差及合攏力。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","壓力乘密封跨距即可直接得到所有位置的膜張力"],"optionsEn":["An omitted chamber connected to external water produces the wrong pressure difference and closure force.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Pressure times seal span directly gives membrane tension at every location"],"answer":0,"explanation":"漏列與外水連通的腔室，錯算有效壓差及合攏力。 需以量測區分可能原因。","explanationEn":"An omitted chamber connected to external water produces the wrong pressure difference and closure force. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b170-v14-13","title":"次級密封與膜面荷載：機制與系統路徑","titleEn":"Secondary seals and membrane loading: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-12"],"objective":"說明「次級密封與膜面荷載」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Secondary seals and membrane loading” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"Omega 類次級密封容許接頭相對位移，並提供與主密封不同的水密屏障。壓力乘跨距是每單位長度的橫向合力，不是膜張力；張力還取決於鼓出幾何、邊界固定和材料變形，夾具與角部不能從均勻薄膜模型略去。 判別這個機制時，應觀察把次級膜鼓出形狀、夾具位移與壓差試驗結果連結；若出現把橫向合力誤當膜張力，漏估夾持區剝離與角部應變，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「次級密封與膜面荷載」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"An Omega-type secondary seal accommodates relative movement and forms a barrier distinct from the primary seal. Pressure times span gives transverse resultant per unit length, not membrane tension. Tension also depends on bulging geometry, restraints and material deformation; clamps and corners require separate assessment. Use the following check to discriminate the mechanism: Relate secondary-membrane bulge, clamp movement and differential-pressure tests. If treating transverse resultant as tension misses clamp peeling and corner strain, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Secondary seals and membrane loading” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension.","failure":"常見誤解：「壓力乘密封跨距即可直接得到所有位置的膜張力」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Pressure times seal span directly gives membrane tension at every location\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「次級密封與膜面荷載」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Secondary seals and membrane loading”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-13-k1","title":"次級密封與膜面荷載","titleEn":"Secondary seals and membrane loading","text":"Omega 類次級密封容許接頭相對位移，並提供與主密封不同的水密屏障。壓力乘跨距是每單位長度的橫向合力，不是膜張力；張力還取決於鼓出幾何、邊界固定和材料變形，夾具與角部不能從均勻薄膜模型略去。","textEn":"An Omega-type secondary seal accommodates relative movement and forms a barrier distinct from the primary seal. Pressure times span gives transverse resultant per unit length, not membrane tension.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：壓力乘密封跨距即可直接得到所有位置的膜張力 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Pressure times seal span directly gives membrane tension at every location Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「次級密封與膜面荷載」，下列哪一項敘述正確？","questionEn":"Which statement about \"Secondary seals and membrane loading\" is correct?","options":["壓力乘密封跨距即可直接得到所有位置的膜張力","Omega 類次級密封容許接頭相對位移，並提供與主密封不同的水密屏障。","長管節的自由熱伸縮必定全部集中在單一接頭"],"optionsEn":["Pressure times seal span directly gives membrane tension at every location","An Omega-type secondary seal accommodates relative movement and forms a barrier distinct from the primary seal.","All free thermal expansion of a long element concentrates at one joint"],"answer":1,"explanation":"Omega 類次級密封容許接頭相對位移，並提供與主密封不同的水密屏障。 其餘選項是常見誤解。","explanationEn":"An Omega-type secondary seal accommodates relative movement and forms a barrier distinct from the primary seal. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b170-v14-14","title":"次級密封與膜面荷載：定量估算","titleEn":"Secondary seals and membrane loading: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-13"],"objective":"以數值模型估算「次級密封與膜面荷載」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Secondary seals and membrane loading” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：把次級膜鼓出形狀、夾具位移與壓差試驗結果連結。","observationEn":"How to cross-check: Relate secondary-membrane bulge, clamp movement and differential-pressure tests.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「次級密封與膜面荷載」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Secondary seals and membrane loading\", which statement holds?","options":["剪力鍵外觀面積全部都會同時均勻承受剪力","壓縮量固定就表示橡膠密封反力永遠不會降低","原創教學假設：transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension。"],"optionsEn":["The full visible shear-key area always carries shear uniformly","Fixed compression means rubber sealing reaction never decreases over time","Original teaching assumptions: transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension."],"answer":2,"explanation":"原創教學假設：transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension。 重算時請保留單位。","explanationEn":"Original teaching assumptions: transverseResultantPerLength=p*span=0.20 MPa*0.30 m=60 kN/m; this is not membrane tension. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b170-v14-15","title":"次級密封與膜面荷載：試驗與驗證","titleEn":"Secondary seals and membrane loading: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「次級密封與膜面荷載」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Secondary seals and membrane loading” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"把次級膜鼓出形狀、夾具位移與壓差試驗結果連結。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「把橫向合力誤當膜張力，漏估夾持區剝離與角部應變」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Relate secondary-membrane bulge, clamp movement and differential-pressure tests. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Treating transverse resultant as tension misses clamp peeling and corner strain. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將把次級膜鼓出形狀、夾具位移與壓差試驗結果連結列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現把橫向合力誤當膜張力，漏估夾持區剝離與角部應變，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Relate secondary-membrane bulge, clamp movement and differential-pressure tests. Link results to location, material batch and interpretation version. If treating transverse resultant as tension misses clamp peeling and corner strain, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：把橫向合力誤當膜張力，漏估夾持區剝離與角部應變。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Treating transverse resultant as tension misses clamp peeling and corner strain. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-15-k1","title":"驗證方法","titleEn":"Verification method","text":"把次級膜鼓出形狀、夾具位移與壓差試驗結果連結。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「把橫向合力誤當膜張力，漏估夾持區剝離與角部應變」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Relate secondary-membrane bulge, clamp movement and differential-pressure tests. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Treating transverse resultant as tension misses clamp peeling and corner strain. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-15-k2","title":"現場實務","titleEn":"Site practice","text":"將把次級膜鼓出形狀、夾具位移與壓差試驗結果連結列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現把橫向合力誤當膜張力，漏估夾持區剝離與角部應變，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Relate secondary-membrane bulge, clamp movement and differential-pressure tests. Link results to location, material batch and interpretation version. If treating transverse resultant as tension misses clamp peeling and corner strain, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「次級密封與膜面荷載」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Secondary seals and membrane loading\"?","options":["把次級膜鼓出形狀、夾具位移與壓差試驗結果連結。","不確定度太難估計，報告中只寫最佳值即可。","兩管節中心對準就代表周邊密封必定均勻接觸"],"optionsEn":["Relate secondary-membrane bulge, clamp movement and differential-pressure tests.","Uncertainty is too hard to estimate, so the report may state only the best value.","Aligned element centers guarantee uniform contact around the entire seal"],"answer":0,"explanation":"把次級膜鼓出形狀、夾具位移與壓差試驗結果連結。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Relate secondary-membrane bulge, clamp movement and differential-pressure tests. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b170-v14-16","title":"次級密封與膜面荷載：失效診斷","titleEn":"Secondary seals and membrane loading: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-15"],"objective":"從症狀倒推「次級密封與膜面荷載」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Secondary seals and membrane loading” and propose discriminating checks, corrective actions and prevention.","instruction":"把橫向合力誤當膜張力，漏估夾持區剝離與角部應變。相似表徵也可能由量測偏差造成，因此應回到把次級膜鼓出形狀、夾具位移與壓差試驗結果連結，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Treating transverse resultant as tension misses clamp peeling and corner strain. Similar symptoms can arise from measurement bias: return to relate secondary-membrane bulge, clamp movement and differential-pressure tests to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察把次級膜鼓出形狀、夾具位移與壓差試驗結果連結；若出現把橫向合力誤當膜張力，漏估夾持區剝離與角部應變，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If treating transverse resultant as tension misses clamp peeling and corner strain, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「壓力乘密封跨距即可直接得到所有位置的膜張力」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Pressure times seal span directly gives membrane tension at every location\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-16-k1","title":"失效模式","titleEn":"Failure mode","text":"把橫向合力誤當膜張力，漏估夾持區剝離與角部應變。相似表徵也可能由量測偏差造成，因此應回到把次級膜鼓出形狀、夾具位移與壓差試驗結果連結，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"Treating transverse resultant as tension misses clamp peeling and corner strain. Similar symptoms can arise from measurement bias: return to relate secondary-membrane bulge, clamp movement and differential-pressure tests to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「次級密封與膜面荷載」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Secondary seals and membrane loading\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","把橫向合力誤當膜張力，漏估夾持區剝離與角部應變。","長管節的自由熱伸縮必定全部集中在單一接頭"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Treating transverse resultant as tension misses clamp peeling and corner strain.","All free thermal expansion of a long element concentrates at one joint"],"answer":1,"explanation":"把橫向合力誤當膜張力，漏估夾持區剝離與角部應變。 需以量測區分可能原因。","explanationEn":"Treating transverse resultant as tension misses clamp peeling and corner strain. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b170-v14-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「溫度伸縮與軸向位移」與「差異沉陷與接頭轉角」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Thermal expansion and axial movement\" and \"Differential settlement and joint rotation\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b170-v14-17","title":"溫度伸縮與軸向位移：機制與系統路徑","titleEn":"Thermal expansion and axial movement: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-16"],"objective":"說明「溫度伸縮與軸向位移」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Thermal expansion and axial movement” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"管節溫度改變可能透過接頭釋放位移，也可能因基床摩擦和相鄰約束累積軸力。自由伸縮是假想無拘束上限情境之一，不能同時又假定全拘束應力；維護判讀須對應量測溫度與實際滑移邊界，分開季節變化和永久漂移。 判別這個機制時，應觀察比較管節溫度、接頭軸向開度及長期位置趨勢；若出現季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「溫度伸縮與軸向位移」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Element temperature changes can release movement at joints or accumulate force through bedding friction and neighboring restraints. Free expansion is a hypothetical unrestrained case and cannot simultaneously imply full-restraint stress. Relate monitoring temperature to slip boundaries to separate seasonal changes from permanent drift. Use the following check to discriminate the mechanism: Compare element temperature, axial joint opening and long-term position trends. If seasonal opening is mistaken for settlement or averaging conceals permanent drift, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Thermal expansion and axial movement” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m.","failure":"常見誤解：「長管節的自由熱伸縮必定全部集中在單一接頭」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"All free thermal expansion of a long element concentrates at one joint\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「溫度伸縮與軸向位移」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Thermal expansion and axial movement”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-17-k1","title":"溫度伸縮與軸向位移","titleEn":"Thermal expansion and axial movement","text":"管節溫度改變可能透過接頭釋放位移，也可能因基床摩擦和相鄰約束累積軸力。自由伸縮是假想無拘束上限情境之一，不能同時又假定全拘束應力；維護判讀須對應量測溫度與實際滑移邊界，分開季節變化和永久漂移。","textEn":"Element temperature changes can release movement at joints or accumulate force through bedding friction and neighboring restraints. Free expansion is a hypothetical unrestrained case and cannot simultaneously imply full-restraint stress.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：長管節的自由熱伸縮必定全部集中在單一接頭 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: All free thermal expansion of a long element concentrates at one joint Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「溫度伸縮與軸向位移」，下列哪一項敘述正確？","questionEn":"Which statement about \"Thermal expansion and axial movement\" is correct?","options":["長管節的自由熱伸縮必定全部集中在單一接頭","量測接頭中央一個開度就能代表整圈密封變形","管節溫度改變可能透過接頭釋放位移，也可能因基床摩擦和相鄰約束累積軸力。"],"optionsEn":["All free thermal expansion of a long element concentrates at one joint","One central opening measurement represents deformation around the entire seal","Element temperature changes can release movement at joints or accumulate force through bedding friction and neighboring restraints."],"answer":2,"explanation":"管節溫度改變可能透過接頭釋放位移，也可能因基床摩擦和相鄰約束累積軸力。 其餘選項是常見誤解。","explanationEn":"Element temperature changes can release movement at joints or accumulate force through bedding friction and neighboring restraints. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b170-v14-18","title":"溫度伸縮與軸向位移：定量估算","titleEn":"Thermal expansion and axial movement: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-17"],"objective":"以數值模型估算「溫度伸縮與軸向位移」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Thermal expansion and axial movement” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：比較管節溫度、接頭軸向開度及長期位置趨勢。","observationEn":"How to cross-check: Compare element temperature, axial joint opening and long-term position trends.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「溫度伸縮與軸向位移」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Thermal expansion and axial movement\", which statement holds?","options":["原創教學假設：freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m。","接頭集水少就能證明主次兩道密封都毫無缺陷","只要安裝兩道密封就必定得到完全獨立的雙重保障"],"optionsEn":["Original teaching assumptions: freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m.","Low collected joint flow proves both primary and secondary seals are defect-free","Installing two seals always creates completely independent redundant protection"],"answer":0,"explanation":"原創教學假設：freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m。 重算時請保留單位。","explanationEn":"Original teaching assumptions: freeExpansion=alpha*L*dT=1e-5/K*200 m*15 K=0.030 m. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b170-v14-19","title":"溫度伸縮與軸向位移：試驗與驗證","titleEn":"Thermal expansion and axial movement: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「溫度伸縮與軸向位移」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Thermal expansion and axial movement” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"比較管節溫度、接頭軸向開度及長期位置趨勢。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare element temperature, axial joint opening and long-term position trends. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Seasonal opening is mistaken for settlement or averaging conceals permanent drift. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將比較管節溫度、接頭軸向開度及長期位置趨勢列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Compare element temperature, axial joint opening and long-term position trends. Link results to location, material batch and interpretation version. If seasonal opening is mistaken for settlement or averaging conceals permanent drift, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Seasonal opening is mistaken for settlement or averaging conceals permanent drift. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-19-k1","title":"驗證方法","titleEn":"Verification method","text":"比較管節溫度、接頭軸向開度及長期位置趨勢。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Compare element temperature, axial joint opening and long-term position trends. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Seasonal opening is mistaken for settlement or averaging conceals permanent drift. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-19-k2","title":"現場實務","titleEn":"Site practice","text":"將比較管節溫度、接頭軸向開度及長期位置趨勢列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Compare element temperature, axial joint opening and long-term position trends. Link results to location, material batch and interpretation version. If seasonal opening is mistaken for settlement or averaging conceals permanent drift, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「溫度伸縮與軸向位移」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Thermal expansion and axial movement\"?","options":["允收準則可以等看到量測數據後再決定。","比較管節溫度、接頭軸向開度及長期位置趨勢。","橡膠壓縮率相同就代表任何密封斷面的反力相同"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Compare element temperature, axial joint opening and long-term position trends.","Equal rubber compression ratios imply equal reaction for every seal profile"],"answer":1,"explanation":"比較管節溫度、接頭軸向開度及長期位置趨勢。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare element temperature, axial joint opening and long-term position trends. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b170-v14-20","title":"溫度伸縮與軸向位移：失效診斷","titleEn":"Thermal expansion and axial movement: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-19"],"objective":"從症狀倒推「溫度伸縮與軸向位移」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Thermal expansion and axial movement” and propose discriminating checks, corrective actions and prevention.","instruction":"季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋。相似表徵也可能由量測偏差造成，因此應回到比較管節溫度、接頭軸向開度及長期位置趨勢，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Seasonal opening is mistaken for settlement or averaging conceals permanent drift. Similar symptoms can arise from measurement bias: return to compare element temperature, axial joint opening and long-term position trends to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察比較管節溫度、接頭軸向開度及長期位置趨勢；若出現季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If seasonal opening is mistaken for settlement or averaging conceals permanent drift, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「長管節的自由熱伸縮必定全部集中在單一接頭」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"All free thermal expansion of a long element concentrates at one joint\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-20-k1","title":"失效模式","titleEn":"Failure mode","text":"季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋。相似表徵也可能由量測偏差造成，因此應回到比較管節溫度、接頭軸向開度及長期位置趨勢，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"Seasonal opening is mistaken for settlement or averaging conceals permanent drift. Similar symptoms can arise from measurement bias: return to compare element temperature, axial joint opening and long-term position trends to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「溫度伸縮與軸向位移」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Thermal expansion and axial movement\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","量測接頭中央一個開度就能代表整圈密封變形","季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","One central opening measurement represents deformation around the entire seal","Seasonal opening is mistaken for settlement or averaging conceals permanent drift."],"answer":2,"explanation":"季節開度被誤判永久沉陷，或永久漂移被季節平均掩蓋。 需以量測區分可能原因。","explanationEn":"Seasonal opening is mistaken for settlement or averaging conceals permanent drift. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b170-v14-21","title":"差異沉陷與接頭轉角：機制與系統路徑","titleEn":"Differential settlement and joint rotation: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-20"],"objective":"說明「差異沉陷與接頭轉角」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Differential settlement and joint rotation” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"相鄰基床沉陷差使接頭發生轉角和剪位移，密封上緣與下緣的開度因而不同。本算例假定一管節為剛體且相鄰管節維持水平，因此單段弦傾角等於接頭相對轉角；若兩側都轉動，應改用兩側斜率差。管節本身彎曲及接頭剪力鍵約束也會重新分配變形；必須同時觀察接頭和管節的長基線高程。 判別這個機制時，應觀察比較長基線沉陷、接頭四角開度與剪位移；若出現單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「差異沉陷與接頭轉角」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Differential bedding settlement rotates and shears a joint, producing different openings at its top and bottom. This example assumes one rigid element beside a horizontal neighbor, so its chord inclination equals relative joint rotation. If both sides rotate, use their slope difference instead. Element bending and shear-key restraints also redistribute movement. Monitor both the joint and long-baseline element elevations to distinguish these contributions. Use the following check to discriminate the mechanism: Compare long-baseline settlement, four-corner opening and joint shear movement. If one normal opening measurement conceals corner differences and rotation-induced local unloading, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Differential settlement and joint rotation” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m.","failure":"常見誤解：「量測接頭中央一個開度就能代表整圈密封變形」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"One central opening measurement represents deformation around the entire seal\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「差異沉陷與接頭轉角」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Differential settlement and joint rotation”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-21-k1","title":"差異沉陷與接頭轉角","titleEn":"Differential settlement and joint rotation","text":"相鄰基床沉陷差使接頭發生轉角和剪位移，密封上緣與下緣的開度因而不同。本算例假定一管節為剛體且相鄰管節維持水平，因此單段弦傾角等於接頭相對轉角；若兩側都轉動，應改用兩側斜率差。","textEn":"Differential bedding settlement rotates and shears a joint, producing different openings at its top and bottom. This example assumes one rigid element beside a horizontal neighbor, so its chord inclination equals relative joint rotation.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：量測接頭中央一個開度就能代表整圈密封變形 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: One central opening measurement represents deformation around the entire seal Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「差異沉陷與接頭轉角」，下列哪一項敘述正確？","questionEn":"Which statement about \"Differential settlement and joint rotation\" is correct?","options":["相鄰基床沉陷差使接頭發生轉角和剪位移，密封上緣與下緣的開度因而不同。","量測接頭中央一個開度就能代表整圈密封變形","剪力鍵外觀面積全部都會同時均勻承受剪力"],"optionsEn":["Differential bedding settlement rotates and shears a joint, producing different openings at its top and bottom.","One central opening measurement represents deformation around the entire seal","The full visible shear-key area always carries shear uniformly"],"answer":0,"explanation":"相鄰基床沉陷差使接頭發生轉角和剪位移，密封上緣與下緣的開度因而不同。 其餘選項是常見誤解。","explanationEn":"Differential bedding settlement rotates and shears a joint, producing different openings at its top and bottom. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b170-v14-22","title":"差異沉陷與接頭轉角：定量估算","titleEn":"Differential settlement and joint rotation: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-21"],"objective":"以數值模型估算「差異沉陷與接頭轉角」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Differential settlement and joint rotation” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：比較長基線沉陷、接頭四角開度與剪位移。","observationEn":"How to cross-check: Compare long-baseline settlement, four-corner opening and joint shear movement.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「差異沉陷與接頭轉角」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Differential settlement and joint rotation\", which statement holds?","options":["壓縮量固定就表示橡膠密封反力永遠不會降低","原創教學假設：relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m。","兩管節中心對準就代表周邊密封必定均勻接觸"],"optionsEn":["Fixed compression means rubber sealing reaction never decreases over time","Original teaching assumptions: relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor.","Aligned element centers guarantee uniform contact around the entire seal"],"answer":1,"explanation":"原創教學假設：relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m。 重算時請保留單位。","explanationEn":"Original teaching assumptions: relativeJointRotation=0.020 m/200 m=0.00010 rad only for a rigid element beside a horizontal neighbor; openingDifference=relativeJointRotation*10 m=0.001 m. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b170-v14-23","title":"差異沉陷與接頭轉角：試驗與驗證","titleEn":"Differential settlement and joint rotation: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「差異沉陷與接頭轉角」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Differential settlement and joint rotation” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"比較長基線沉陷、接頭四角開度與剪位移。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare long-baseline settlement, four-corner opening and joint shear movement. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: One normal opening measurement conceals corner differences and rotation-induced local unloading. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將比較長基線沉陷、接頭四角開度與剪位移列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Compare long-baseline settlement, four-corner opening and joint shear movement. Link results to location, material batch and interpretation version. If one normal opening measurement conceals corner differences and rotation-induced local unloading, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: One normal opening measurement conceals corner differences and rotation-induced local unloading. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-23-k1","title":"驗證方法","titleEn":"Verification method","text":"比較長基線沉陷、接頭四角開度與剪位移。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Compare long-baseline settlement, four-corner opening and joint shear movement. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: One normal opening measurement conceals corner differences and rotation-induced local unloading. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-23-k2","title":"現場實務","titleEn":"Site practice","text":"將比較長基線沉陷、接頭四角開度與剪位移列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Compare long-baseline settlement, four-corner opening and joint shear movement. Link results to location, material batch and interpretation version. If one normal opening measurement conceals corner differences and rotation-induced local unloading, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「差異沉陷與接頭轉角」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Differential settlement and joint rotation\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","外水壓乘全部濕表面就等於接頭軸向合攏力","比較長基線沉陷、接頭四角開度與剪位移。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","External pressure times every wet surface equals the axial joint-closing force","Compare long-baseline settlement, four-corner opening and joint shear movement."],"answer":2,"explanation":"比較長基線沉陷、接頭四角開度與剪位移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare long-baseline settlement, four-corner opening and joint shear movement. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b170-v14-24","title":"差異沉陷與接頭轉角：失效診斷","titleEn":"Differential settlement and joint rotation: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-23"],"objective":"從症狀倒推「差異沉陷與接頭轉角」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Differential settlement and joint rotation” and propose discriminating checks, corrective actions and prevention.","instruction":"單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓。相似表徵也可能由量測偏差造成，因此應回到比較長基線沉陷、接頭四角開度與剪位移，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"One normal opening measurement conceals corner differences and rotation-induced local unloading. Similar symptoms can arise from measurement bias: return to compare long-baseline settlement, four-corner opening and joint shear movement to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察比較長基線沉陷、接頭四角開度與剪位移；若出現單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If one normal opening measurement conceals corner differences and rotation-induced local unloading, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「量測接頭中央一個開度就能代表整圈密封變形」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"One central opening measurement represents deformation around the entire seal\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-24-k1","title":"失效模式","titleEn":"Failure mode","text":"單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓。相似表徵也可能由量測偏差造成，因此應回到比較長基線沉陷、接頭四角開度與剪位移，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"One normal opening measurement conceals corner differences and rotation-induced local unloading. Similar symptoms can arise from measurement bias: return to compare long-baseline settlement, four-corner opening and joint shear movement to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「差異沉陷與接頭轉角」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Differential settlement and joint rotation\" shows distress, which diagnosis is most reasonable?","options":["單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓。","只要結構還沒倒，就代表安全餘裕仍然足夠。","剪力鍵外觀面積全部都會同時均勻承受剪力"],"optionsEn":["One normal opening measurement conceals corner differences and rotation-induced local unloading.","As long as the structure is still standing, its safety margin must still be adequate.","The full visible shear-key area always carries shear uniformly"],"answer":0,"explanation":"單點開度正常卻四角變化不一致，漏掉轉角造成的局部卸壓。 需以量測區分可能原因。","explanationEn":"One normal opening measurement conceals corner differences and rotation-induced local unloading. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b170-v14-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「剪力鍵承壓與接觸偏心」與「分區滲漏與來源辨識」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Shear-key bearing and eccentric contact\" and \"Compartment leakage and source diagnosis\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b170-v14-25","title":"剪力鍵承壓與接觸偏心：機制與系統路徑","titleEn":"Shear-key bearing and eccentric contact: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-24"],"objective":"說明「剪力鍵承壓與接觸偏心」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Shear-key bearing and eccentric contact” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"剪力鍵限制管節相對橫移並將剪力傳給混凝土，接觸位置取決於間隙、裝配與差異沉陷。平均承壓只適用已知有效面積，邊緣接觸會伴隨劈裂和局部彎曲；不能把整塊外觀面積直接當作同時承壓面。 判別這個機制時，應觀察核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫；若出現鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「剪力鍵承壓與接觸偏心」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Shear keys restrain relative transverse movement and transmit shear into concrete, with contact governed by gaps, assembly and settlement. Average bearing requires a known effective area; edge contact introduces splitting and local bending. The whole visible face is not automatically active bearing area. Use the following check to discriminate the mechanism: Check shear-key gaps, contact marks and nearby concrete cracks. If corner-first contact splits concrete while an average bearing calculation remains low, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Shear-key bearing and eccentric contact” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa.","failure":"常見誤解：「剪力鍵外觀面積全部都會同時均勻承受剪力」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The full visible shear-key area always carries shear uniformly\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「剪力鍵承壓與接觸偏心」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Shear-key bearing and eccentric contact”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-25-k1","title":"剪力鍵承壓與接觸偏心","titleEn":"Shear-key bearing and eccentric contact","text":"剪力鍵限制管節相對橫移並將剪力傳給混凝土，接觸位置取決於間隙、裝配與差異沉陷。平均承壓只適用已知有效面積，邊緣接觸會伴隨劈裂和局部彎曲；不能把整塊外觀面積直接當作同時承壓面。","textEn":"Shear keys restrain relative transverse movement and transmit shear into concrete, with contact governed by gaps, assembly and settlement. Average bearing requires a known effective area; edge contact introduces splitting and local bending.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：剪力鍵外觀面積全部都會同時均勻承受剪力 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The full visible shear-key area always carries shear uniformly Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「剪力鍵承壓與接觸偏心」，下列哪一項敘述正確？","questionEn":"Which statement about \"Shear-key bearing and eccentric contact\" is correct?","options":["剪力鍵外觀面積全部都會同時均勻承受剪力","剪力鍵限制管節相對橫移並將剪力傳給混凝土，接觸位置取決於間隙、裝配與差異沉陷。","接頭集水少就能證明主次兩道密封都毫無缺陷"],"optionsEn":["The full visible shear-key area always carries shear uniformly","Shear keys restrain relative transverse movement and transmit shear into concrete, with contact governed by gaps, assembly and settlement.","Low collected joint flow proves both primary and secondary seals are defect-free"],"answer":1,"explanation":"剪力鍵限制管節相對橫移並將剪力傳給混凝土，接觸位置取決於間隙、裝配與差異沉陷。 其餘選項是常見誤解。","explanationEn":"Shear keys restrain relative transverse movement and transmit shear into concrete, with contact governed by gaps, assembly and settlement. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b170-v14-26","title":"剪力鍵承壓與接觸偏心：定量估算","titleEn":"Shear-key bearing and eccentric contact: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-25"],"objective":"以數值模型估算「剪力鍵承壓與接觸偏心」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Shear-key bearing and eccentric contact” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫。","observationEn":"How to cross-check: Check shear-key gaps, contact marks and nearby concrete cracks.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「剪力鍵承壓與接觸偏心」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Shear-key bearing and eccentric contact\", which statement holds?","options":["只要安裝兩道密封就必定得到完全獨立的雙重保障","橡膠壓縮率相同就代表任何密封斷面的反力相同","原創教學假設：meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa。"],"optionsEn":["Installing two seals always creates completely independent redundant protection","Equal rubber compression ratios imply equal reaction for every seal profile","Original teaching assumptions: meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa."],"answer":2,"explanation":"原創教學假設：meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa。 重算時請保留單位。","explanationEn":"Original teaching assumptions: meanBearing=shear/effectiveArea=1000 kN/0.50 m2=2000 kPa=2 MPa. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b170-v14-27","title":"剪力鍵承壓與接觸偏心：試驗與驗證","titleEn":"Shear-key bearing and eccentric contact: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「剪力鍵承壓與接觸偏心」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Shear-key bearing and eccentric contact” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check shear-key gaps, contact marks and nearby concrete cracks. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Corner-first contact splits concrete while an average bearing calculation remains low. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Check shear-key gaps, contact marks and nearby concrete cracks. Link results to location, material batch and interpretation version. If corner-first contact splits concrete while an average bearing calculation remains low, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Corner-first contact splits concrete while an average bearing calculation remains low. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-27-k1","title":"驗證方法","titleEn":"Verification method","text":"核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Check shear-key gaps, contact marks and nearby concrete cracks. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Corner-first contact splits concrete while an average bearing calculation remains low. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-27-k2","title":"現場實務","titleEn":"Site practice","text":"將核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Check shear-key gaps, contact marks and nearby concrete cracks. Link results to location, material batch and interpretation version. If corner-first contact splits concrete while an average bearing calculation remains low, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「剪力鍵承壓與接觸偏心」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Shear-key bearing and eccentric contact\"?","options":["核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫。","量測時不必記錄溫度、水頭、開挖序列與施工荷重，因為它們不會影響結果。","壓力乘密封跨距即可直接得到所有位置的膜張力"],"optionsEn":["Check shear-key gaps, contact marks and nearby concrete cracks.","Temperature, water head, excavation sequence and construction loads need not be recorded because they cannot affect the result.","Pressure times seal span directly gives membrane tension at every location"],"answer":0,"explanation":"核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check shear-key gaps, contact marks and nearby concrete cracks. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b170-v14-28","title":"剪力鍵承壓與接觸偏心：失效診斷","titleEn":"Shear-key bearing and eccentric contact: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-27"],"objective":"從症狀倒推「剪力鍵承壓與接觸偏心」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Shear-key bearing and eccentric contact” and propose discriminating checks, corrective actions and prevention.","instruction":"鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低。相似表徵也可能由量測偏差造成，因此應回到核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Corner-first contact splits concrete while an average bearing calculation remains low. Similar symptoms can arise from measurement bias: return to check shear-key gaps, contact marks and nearby concrete cracks to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫；若出現鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If corner-first contact splits concrete while an average bearing calculation remains low, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「剪力鍵外觀面積全部都會同時均勻承受剪力」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The full visible shear-key area always carries shear uniformly\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-28-k1","title":"失效模式","titleEn":"Failure mode","text":"鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低。相似表徵也可能由量測偏差造成，因此應回到核對剪力鍵間隙、接觸痕跡與鄰近混凝土裂縫，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"Corner-first contact splits concrete while an average bearing calculation remains low. Similar symptoms can arise from measurement bias: return to check shear-key gaps, contact marks and nearby concrete cracks to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「剪力鍵承壓與接觸偏心」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Shear-key bearing and eccentric contact\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低。","接頭集水少就能證明主次兩道密封都毫無缺陷"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Corner-first contact splits concrete while an average bearing calculation remains low.","Low collected joint flow proves both primary and secondary seals are defect-free"],"answer":1,"explanation":"鍵角先接觸引發混凝土劈裂，平均承壓計算仍顯示偏低。 需以量測區分可能原因。","explanationEn":"Corner-first contact splits concrete while an average bearing calculation remains low. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b170-v14-29","title":"分區滲漏與來源辨識：機制與系統路徑","titleEn":"Compartment leakage and source diagnosis: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-28"],"objective":"說明「分區滲漏與來源辨識」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Compartment leakage and source diagnosis” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"接頭集水量可能來自主密封、次級密封、螺栓穿孔或周邊施工縫，不是單憑出水位置就能定位缺口。比較分區壓力與時間響應可縮小來源，總流量還受外水位影響；低流量不能證明兩重屏障均保持完整。 判別這個機制時，應觀察同步記錄分區水壓、集水量及外水位變化；若出現匯集管混接使異處滲水被歸因接頭，修繕後流量不降，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「分區滲漏與來源辨識」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Collected joint water can originate at primary seals, secondary seals, penetrations or adjacent construction joints. Outlet location alone does not locate the breach. Compartment pressure and time response narrow the source, while external water level affects total flow; low flow does not demonstrate two intact barriers. Use the following check to discriminate the mechanism: Record compartment pressure, collected flow and external water-level changes together. If combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Compartment leakage and source diagnosis” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：collectedFlow=12 L/30 min=0.40 L/min。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: collectedFlow=12 L/30 min=0.40 L/min.","failure":"常見誤解：「接頭集水少就能證明主次兩道密封都毫無缺陷」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Low collected joint flow proves both primary and secondary seals are defect-free\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「分區滲漏與來源辨識」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Compartment leakage and source diagnosis”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-29-k1","title":"分區滲漏與來源辨識","titleEn":"Compartment leakage and source diagnosis","text":"接頭集水量可能來自主密封、次級密封、螺栓穿孔或周邊施工縫，不是單憑出水位置就能定位缺口。比較分區壓力與時間響應可縮小來源，總流量還受外水位影響；低流量不能證明兩重屏障均保持完整。","textEn":"Collected joint water can originate at primary seals, secondary seals, penetrations or adjacent construction joints. Outlet location alone does not locate the breach.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：接頭集水少就能證明主次兩道密封都毫無缺陷 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Low collected joint flow proves both primary and secondary seals are defect-free Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「分區滲漏與來源辨識」，下列哪一項敘述正確？","questionEn":"Which statement about \"Compartment leakage and source diagnosis\" is correct?","options":["接頭集水少就能證明主次兩道密封都毫無缺陷","壓縮量固定就表示橡膠密封反力永遠不會降低","接頭集水量可能來自主密封、次級密封、螺栓穿孔或周邊施工縫，不是單憑出水位置就能定位缺口。"],"optionsEn":["Low collected joint flow proves both primary and secondary seals are defect-free","Fixed compression means rubber sealing reaction never decreases over time","Collected joint water can originate at primary seals, secondary seals, penetrations or adjacent construction joints."],"answer":2,"explanation":"接頭集水量可能來自主密封、次級密封、螺栓穿孔或周邊施工縫，不是單憑出水位置就能定位缺口。 其餘選項是常見誤解。","explanationEn":"Collected joint water can originate at primary seals, secondary seals, penetrations or adjacent construction joints. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b170-v14-30","title":"分區滲漏與來源辨識：定量估算","titleEn":"Compartment leakage and source diagnosis: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-29"],"objective":"以數值模型估算「分區滲漏與來源辨識」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Compartment leakage and source diagnosis” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：collectedFlow=12 L/30 min=0.40 L/min。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: collectedFlow=12 L/30 min=0.40 L/min. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同步記錄分區水壓、集水量及外水位變化。","observationEn":"How to cross-check: Record compartment pressure, collected flow and external water-level changes together.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：collectedFlow=12 L/30 min=0.40 L/min。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: collectedFlow=12 L/30 min=0.40 L/min. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「分區滲漏與來源辨識」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Compartment leakage and source diagnosis\", which statement holds?","options":["原創教學假設：collectedFlow=12 L/30 min=0.40 L/min。","兩管節中心對準就代表周邊密封必定均勻接觸","外水壓乘全部濕表面就等於接頭軸向合攏力"],"optionsEn":["Original teaching assumptions: collectedFlow=12 L/30 min=0.40 L/min.","Aligned element centers guarantee uniform contact around the entire seal","External pressure times every wet surface equals the axial joint-closing force"],"answer":0,"explanation":"原創教學假設：collectedFlow=12 L/30 min=0.40 L/min。 重算時請保留單位。","explanationEn":"Original teaching assumptions: collectedFlow=12 L/30 min=0.40 L/min. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b170-v14-31","title":"分區滲漏與來源辨識：試驗與驗證","titleEn":"Compartment leakage and source diagnosis: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「分區滲漏與來源辨識」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Compartment leakage and source diagnosis” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同步記錄分區水壓、集水量及外水位變化。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「匯集管混接使異處滲水被歸因接頭，修繕後流量不降」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Record compartment pressure, collected flow and external water-level changes together. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將同步記錄分區水壓、集水量及外水位變化列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現匯集管混接使異處滲水被歸因接頭，修繕後流量不降，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Record compartment pressure, collected flow and external water-level changes together. Link results to location, material batch and interpretation version. If combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：匯集管混接使異處滲水被歸因接頭，修繕後流量不降。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-31-k1","title":"驗證方法","titleEn":"Verification method","text":"同步記錄分區水壓、集水量及外水位變化。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「匯集管混接使異處滲水被歸因接頭，修繕後流量不降」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Record compartment pressure, collected flow and external water-level changes together. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-31-k2","title":"現場實務","titleEn":"Site practice","text":"將同步記錄分區水壓、集水量及外水位變化列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現匯集管混接使異處滲水被歸因接頭，修繕後流量不降，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Record compartment pressure, collected flow and external water-level changes together. Link results to location, material batch and interpretation version. If combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「分區滲漏與來源辨識」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Compartment leakage and source diagnosis\"?","options":["沿用另一條隧道或另一處地層的量測結果，就可視為本工程已完成驗證。","同步記錄分區水壓、集水量及外水位變化。","長管節的自由熱伸縮必定全部集中在單一接頭"],"optionsEn":["Reusing results from another tunnel or ground formation counts as verifying this structure.","Record compartment pressure, collected flow and external water-level changes together.","All free thermal expansion of a long element concentrates at one joint"],"answer":1,"explanation":"同步記錄分區水壓、集水量及外水位變化。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Record compartment pressure, collected flow and external water-level changes together. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b170-v14-32","title":"分區滲漏與來源辨識：失效診斷","titleEn":"Compartment leakage and source diagnosis: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-31"],"objective":"從症狀倒推「分區滲漏與來源辨識」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Compartment leakage and source diagnosis” and propose discriminating checks, corrective actions and prevention.","instruction":"匯集管混接使異處滲水被歸因接頭，修繕後流量不降。相似表徵也可能由量測偏差造成，因此應回到同步記錄分區水壓、集水量及外水位變化，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow. Similar symptoms can arise from measurement bias: return to record compartment pressure, collected flow and external water-level changes together to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察同步記錄分區水壓、集水量及外水位變化；若出現匯集管混接使異處滲水被歸因接頭，修繕後流量不降，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「接頭集水少就能證明主次兩道密封都毫無缺陷」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Low collected joint flow proves both primary and secondary seals are defect-free\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-32-k1","title":"失效模式","titleEn":"Failure mode","text":"匯集管混接使異處滲水被歸因接頭，修繕後流量不降。相似表徵也可能由量測偏差造成，因此應回到同步記錄分區水壓、集水量及外水位變化，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"Combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow. Similar symptoms can arise from measurement bias: return to record compartment pressure, collected flow and external water-level changes together to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「分區滲漏與來源辨識」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Compartment leakage and source diagnosis\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","壓縮量固定就表示橡膠密封反力永遠不會降低","匯集管混接使異處滲水被歸因接頭，修繕後流量不降。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Fixed compression means rubber sealing reaction never decreases over time","Combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow."],"answer":2,"explanation":"匯集管混接使異處滲水被歸因接頭，修繕後流量不降。 需以量測區分可能原因。","explanationEn":"Combined collection lines misattribute remote seepage to a joint and repairs do not reduce flow. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b170-v14-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「應力鬆弛與長期密封」與「屏障獨立性與交接檔案」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Stress relaxation and long-term sealing\" and \"Barrier independence and handover records\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b170-v14-33","title":"應力鬆弛與長期密封：機制與系統路徑","titleEn":"Stress relaxation and long-term sealing: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-32"],"objective":"說明「應力鬆弛與長期密封」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Stress relaxation and long-term sealing” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"橡膠在近固定壓縮下仍會應力鬆弛，溫度、老化和化學環境共同改變長期接觸反力。短期保持率只是特定試驗條件的比較，不是現場壽命或剩餘承壓能力；長期評估需保持幾何變形與材料劣化資料之間的對應。 判別這個機制時，應觀察比較相同壓縮與溫度的保載試驗及接頭歷時位移；若出現將加速試驗小時數直接當服役年數，錯估長期密封反力，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「應力鬆弛與長期密封」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Rubber relaxes under nearly fixed compression, with temperature, aging and chemistry altering long-term contact force. Short-term retention compares specified test conditions, not field lifetime or remaining pressure capacity. Long-term assessment must link material degradation evidence with actual geometric deformation histories. Use the following check to discriminate the mechanism: Compare sustained-compression tests at equal temperature with joint movement histories. If equating accelerated-test hours directly to service years misestimates long-term seal reaction, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Stress relaxation and long-term sealing” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression.","failure":"常見誤解：「壓縮量固定就表示橡膠密封反力永遠不會降低」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Fixed compression means rubber sealing reaction never decreases over time\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「應力鬆弛與長期密封」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Stress relaxation and long-term sealing”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-33-k1","title":"應力鬆弛與長期密封","titleEn":"Stress relaxation and long-term sealing","text":"橡膠在近固定壓縮下仍會應力鬆弛，溫度、老化和化學環境共同改變長期接觸反力。短期保持率只是特定試驗條件的比較，不是現場壽命或剩餘承壓能力；長期評估需保持幾何變形與材料劣化資料之間的對應。","textEn":"Rubber relaxes under nearly fixed compression, with temperature, aging and chemistry altering long-term contact force. Short-term retention compares specified test conditions, not field lifetime or remaining pressure capacity.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：壓縮量固定就表示橡膠密封反力永遠不會降低 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Fixed compression means rubber sealing reaction never decreases over time Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「應力鬆弛與長期密封」，下列哪一項敘述正確？","questionEn":"Which statement about \"Stress relaxation and long-term sealing\" is correct?","options":["橡膠在近固定壓縮下仍會應力鬆弛，溫度、老化和化學環境共同改變長期接觸反力。","壓縮量固定就表示橡膠密封反力永遠不會降低","只要安裝兩道密封就必定得到完全獨立的雙重保障"],"optionsEn":["Rubber relaxes under nearly fixed compression, with temperature, aging and chemistry altering long-term contact force.","Fixed compression means rubber sealing reaction never decreases over time","Installing two seals always creates completely independent redundant protection"],"answer":0,"explanation":"橡膠在近固定壓縮下仍會應力鬆弛，溫度、老化和化學環境共同改變長期接觸反力。 其餘選項是常見誤解。","explanationEn":"Rubber relaxes under nearly fixed compression, with temperature, aging and chemistry altering long-term contact force. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b170-v14-34","title":"應力鬆弛與長期密封：定量估算","titleEn":"Stress relaxation and long-term sealing: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-33"],"objective":"以數值模型估算「應力鬆弛與長期密封」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Stress relaxation and long-term sealing” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：比較相同壓縮與溫度的保載試驗及接頭歷時位移。","observationEn":"How to cross-check: Compare sustained-compression tests at equal temperature with joint movement histories.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「應力鬆弛與長期密封」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Stress relaxation and long-term sealing\", which statement holds?","options":["橡膠壓縮率相同就代表任何密封斷面的反力相同","原創教學假設：forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression。","壓力乘密封跨距即可直接得到所有位置的膜張力"],"optionsEn":["Equal rubber compression ratios imply equal reaction for every seal profile","Original teaching assumptions: forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression.","Pressure times seal span directly gives membrane tension at every location"],"answer":1,"explanation":"原創教學假設：forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression。 重算時請保留單位。","explanationEn":"Original teaching assumptions: forceRetention=180 kN/240 kN=0.75=75 percent at equal imposed compression. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b170-v14-35","title":"應力鬆弛與長期密封：試驗與驗證","titleEn":"Stress relaxation and long-term sealing: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「應力鬆弛與長期密封」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Stress relaxation and long-term sealing” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"比較相同壓縮與溫度的保載試驗及接頭歷時位移。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「將加速試驗小時數直接當服役年數，錯估長期密封反力」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare sustained-compression tests at equal temperature with joint movement histories. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Equating accelerated-test hours directly to service years misestimates long-term seal reaction. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將比較相同壓縮與溫度的保載試驗及接頭歷時位移列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現將加速試驗小時數直接當服役年數，錯估長期密封反力，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Compare sustained-compression tests at equal temperature with joint movement histories. Link results to location, material batch and interpretation version. If equating accelerated-test hours directly to service years misestimates long-term seal reaction, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：將加速試驗小時數直接當服役年數，錯估長期密封反力。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Equating accelerated-test hours directly to service years misestimates long-term seal reaction. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-35-k1","title":"驗證方法","titleEn":"Verification method","text":"比較相同壓縮與溫度的保載試驗及接頭歷時位移。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「將加速試驗小時數直接當服役年數，錯估長期密封反力」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Compare sustained-compression tests at equal temperature with joint movement histories. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: Equating accelerated-test hours directly to service years misestimates long-term seal reaction. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-35-k2","title":"現場實務","titleEn":"Site practice","text":"將比較相同壓縮與溫度的保載試驗及接頭歷時位移列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現將加速試驗小時數直接當服役年數，錯估長期密封反力，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Compare sustained-compression tests at equal temperature with joint movement histories. Link results to location, material batch and interpretation version. If equating accelerated-test hours directly to service years misestimates long-term seal reaction, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「應力鬆弛與長期密封」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Stress relaxation and long-term sealing\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","量測接頭中央一個開度就能代表整圈密封變形","比較相同壓縮與溫度的保載試驗及接頭歷時位移。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","One central opening measurement represents deformation around the entire seal","Compare sustained-compression tests at equal temperature with joint movement histories."],"answer":2,"explanation":"比較相同壓縮與溫度的保載試驗及接頭歷時位移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare sustained-compression tests at equal temperature with joint movement histories. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b170-v14-36","title":"應力鬆弛與長期密封：失效診斷","titleEn":"Stress relaxation and long-term sealing: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-35"],"objective":"從症狀倒推「應力鬆弛與長期密封」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Stress relaxation and long-term sealing” and propose discriminating checks, corrective actions and prevention.","instruction":"將加速試驗小時數直接當服役年數，錯估長期密封反力。相似表徵也可能由量測偏差造成，因此應回到比較相同壓縮與溫度的保載試驗及接頭歷時位移，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Equating accelerated-test hours directly to service years misestimates long-term seal reaction. Similar symptoms can arise from measurement bias: return to compare sustained-compression tests at equal temperature with joint movement histories to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察比較相同壓縮與溫度的保載試驗及接頭歷時位移；若出現將加速試驗小時數直接當服役年數，錯估長期密封反力，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If equating accelerated-test hours directly to service years misestimates long-term seal reaction, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「壓縮量固定就表示橡膠密封反力永遠不會降低」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Fixed compression means rubber sealing reaction never decreases over time\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-36-k1","title":"失效模式","titleEn":"Failure mode","text":"將加速試驗小時數直接當服役年數，錯估長期密封反力。相似表徵也可能由量測偏差造成，因此應回到比較相同壓縮與溫度的保載試驗及接頭歷時位移，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"Equating accelerated-test hours directly to service years misestimates long-term seal reaction. Similar symptoms can arise from measurement bias: return to compare sustained-compression tests at equal temperature with joint movement histories to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「應力鬆弛與長期密封」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Stress relaxation and long-term sealing\" shows distress, which diagnosis is most reasonable?","options":["將加速試驗小時數直接當服役年數，錯估長期密封反力。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","只要安裝兩道密封就必定得到完全獨立的雙重保障"],"optionsEn":["Equating accelerated-test hours directly to service years misestimates long-term seal reaction.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Installing two seals always creates completely independent redundant protection"],"answer":0,"explanation":"將加速試驗小時數直接當服役年數，錯估長期密封反力。 需以量測區分可能原因。","explanationEn":"Equating accelerated-test hours directly to service years misestimates long-term seal reaction. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b170-v14-37","title":"屏障獨立性與交接檔案：機制與系統路徑","titleEn":"Barrier independence and handover records: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-36"],"objective":"說明「屏障獨立性與交接檔案」如何影響沉管水下對接與止水的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Barrier independence and handover records” governs forces, deformation, flow or signals in “Underwater immersed-tube joining and sealing”, and map the relevant inputs, transfer paths and boundaries.","instruction":"主次密封若共用同一失效夾持件或受同一大位移破壞，就不構成完全獨立的備援。交接需對應各屏障試驗、幾何、材料和可檢查部位，完整率僅顯示證據缺口；缺失一項關鍵試驗不能由更多非關鍵紀錄補足。 判別這個機制時，應觀察逐項對照兩道屏障試驗與共同失效構件清單；若出現雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「屏障獨立性與交接檔案」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Primary and secondary seals are not fully independent if they share a failed restraint or suffer the same excessive movement. Handover links separate barrier tests, geometry, materials and accessible locations. Record completeness reveals evidence gaps; many minor records cannot compensate for a missing critical barrier test. Use the following check to discriminate the mechanism: Reconcile individual barrier tests with the inventory of shared failure components. If a shared clamp failure defeats two barriers incorrectly treated as independent redundancy, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Barrier independence and handover records” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創教學假設：traceableTests=18/20=90 percent; completeness is not reliability。","observationEn":"Order-of-magnitude cue: Original teaching assumptions: traceableTests=18/20=90 percent; completeness is not reliability.","failure":"常見誤解：「只要安裝兩道密封就必定得到完全獨立的雙重保障」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Installing two seals always creates completely independent redundant protection\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「屏障獨立性與交接檔案」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Barrier independence and handover records”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b170-v14-37-k1","title":"屏障獨立性與交接檔案","titleEn":"Barrier independence and handover records","text":"主次密封若共用同一失效夾持件或受同一大位移破壞，就不構成完全獨立的備援。交接需對應各屏障試驗、幾何、材料和可檢查部位，完整率僅顯示證據缺口；缺失一項關鍵試驗不能由更多非關鍵紀錄補足。","textEn":"Primary and secondary seals are not fully independent if they share a failed restraint or suffer the same excessive movement. Handover links separate barrier tests, geometry, materials and accessible locations.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要安裝兩道密封就必定得到完全獨立的雙重保障 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Installing two seals always creates completely independent redundant protection Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"關於「屏障獨立性與交接檔案」，下列哪一項敘述正確？","questionEn":"Which statement about \"Barrier independence and handover records\" is correct?","options":["只要安裝兩道密封就必定得到完全獨立的雙重保障","主次密封若共用同一失效夾持件或受同一大位移破壞，就不構成完全獨立的備援。","兩管節中心對準就代表周邊密封必定均勻接觸"],"optionsEn":["Installing two seals always creates completely independent redundant protection","Primary and secondary seals are not fully independent if they share a failed restraint or suffer the same excessive movement.","Aligned element centers guarantee uniform contact around the entire seal"],"answer":1,"explanation":"主次密封若共用同一失效夾持件或受同一大位移破壞，就不構成完全獨立的備援。 其餘選項是常見誤解。","explanationEn":"Primary and secondary seals are not fully independent if they share a failed restraint or suffer the same excessive movement. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b170-v14-38","title":"屏障獨立性與交接檔案：定量估算","titleEn":"Barrier independence and handover records: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-37"],"objective":"以數值模型估算「屏障獨立性與交接檔案」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Barrier independence and handover records” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創教學假設：traceableTests=18/20=90 percent; completeness is not reliability。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original teaching assumptions: traceableTests=18/20=90 percent; completeness is not reliability. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：逐項對照兩道屏障試驗與共同失效構件清單。","observationEn":"How to cross-check: Reconcile individual barrier tests with the inventory of shared failure components.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b170-v14-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創教學假設：traceableTests=18/20=90 percent; completeness is not reliability。接頭算例將剛體位移與橡膠變形分開；實際密封反力需特定斷面、溫度、老化及試驗資料。 此結果僅用來核對量綱及模型敏感度，不是專案設計值、實測紀錄或現場允收門檻。","textEn":"Original teaching assumptions: traceableTests=18/20=90 percent; completeness is not reliability. Joint examples separate rigid-body movement from rubber deformation; actual seal reactions require profile, temperature, aging and test data. This checks dimensions and model sensitivity; it is neither measured project data nor a design or acceptance value.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"依「屏障獨立性與交接檔案」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Barrier independence and handover records\", which statement holds?","options":["外水壓乘全部濕表面就等於接頭軸向合攏力","長管節的自由熱伸縮必定全部集中在單一接頭","原創教學假設：traceableTests=18/20=90 percent; completeness is not reliability。"],"optionsEn":["External pressure times every wet surface equals the axial joint-closing force","All free thermal expansion of a long element concentrates at one joint","Original teaching assumptions: traceableTests=18/20=90 percent; completeness is not reliability."],"answer":2,"explanation":"原創教學假設：traceableTests=18/20=90 percent; completeness is not reliability。 重算時請保留單位。","explanationEn":"Original teaching assumptions: traceableTests=18/20=90 percent; completeness is not reliability. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b170-v14-39","title":"屏障獨立性與交接檔案：試驗與驗證","titleEn":"Barrier independence and handover records: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「屏障獨立性與交接檔案」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Barrier independence and handover records” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"逐項對照兩道屏障試驗與共同失效構件清單。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconcile individual barrier tests with the inventory of shared failure components. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: A shared clamp failure defeats two barriers incorrectly treated as independent redundancy. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將逐項對照兩道屏障試驗與共同失效構件清單列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","observationEn":"Site practice: Apply the following check at handover: Reconcile individual barrier tests with the inventory of shared failure components. Link results to location, material batch and interpretation version. If a shared clamp failure defeats two barriers incorrectly treated as independent redundancy, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","failure":"注意干擾：雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A shared clamp failure defeats two barriers incorrectly treated as independent redundancy. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b170-v14-39-k1","title":"驗證方法","titleEn":"Verification method","text":"逐項對照兩道屏障試驗與共同失效構件清單。量測須保存位置、時間及基準，讓同條件的重複結果可比較；並特別檢查「雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援」是否能由這組資料區分。儀器校核與誤差估計應先於判讀，由負責技師核定該項試驗的允收和停留點。","textEn":"Reconcile individual barrier tests with the inventory of shared failure components. Retain position, time and datums for comparable repeats, specifically distinguishing this scenario: A shared clamp failure defeats two barriers incorrectly treated as independent redundancy. Instrument checks and uncertainty estimates precede interpretation; the responsible engineer sets acceptance and hold points for this test.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-39-k2","title":"現場實務","titleEn":"Site practice","text":"將逐項對照兩道屏障試驗與共同失效構件清單列為該構件的交接證據，連結到施工位置、材料批次及判讀版本。若發現雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援，先保留原始紀錄並由負責技師確認處置，不能以本課算例替代核定作業計畫。","textEn":"Apply the following check at handover: Reconcile individual barrier tests with the inventory of shared failure components. Link results to location, material batch and interpretation version. If a shared clamp failure defeats two barriers incorrectly treated as independent redundancy, retain original records and obtain the responsible engineer's disposition; this example does not replace an approved work plan.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"要驗證「屏障獨立性與交接檔案」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Barrier independence and handover records\"?","options":["逐項對照兩道屏障試驗與共同失效構件清單。","不確定度太難估計，報告中只寫最佳值即可。","剪力鍵外觀面積全部都會同時均勻承受剪力"],"optionsEn":["Reconcile individual barrier tests with the inventory of shared failure components.","Uncertainty is too hard to estimate, so the report may state only the best value.","The full visible shear-key area always carries shear uniformly"],"answer":0,"explanation":"逐項對照兩道屏障試驗與共同失效構件清單。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconcile individual barrier tests with the inventory of shared failure components. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b170-v14-40","title":"屏障獨立性與交接檔案：失效診斷","titleEn":"Barrier independence and handover records: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"prerequisiteIds":["b170-v14-39"],"objective":"從症狀倒推「屏障獨立性與交接檔案」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Barrier independence and handover records” and propose discriminating checks, corrective actions and prevention.","instruction":"雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援。相似表徵也可能由量測偏差造成，因此應回到逐項對照兩道屏障試驗與共同失效構件清單，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A shared clamp failure defeats two barriers incorrectly treated as independent redundancy. Similar symptoms can arise from measurement bias: return to reconcile individual barrier tests with the inventory of shared failure components to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：判別這個機制時，應觀察逐項對照兩道屏障試驗與共同失效構件清單；若出現雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援，便須重新檢查原先假設的接觸、力或水的傳遞邊界，而不能只調整計算結果。","observationEn":"Link to the mechanism: If a shared clamp failure defeats two barriers incorrectly treated as independent redundancy, revisit the assumed contact, force or water-transfer boundary rather than merely adjusting the calculated result.","failure":"誤判風險：若相信「只要安裝兩道密封就必定得到完全獨立的雙重保障」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Installing two seals always creates completely independent redundant protection\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b170-v14-40-k1","title":"失效模式","titleEn":"Failure mode","text":"雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援。相似表徵也可能由量測偏差造成，因此應回到逐項對照兩道屏障試驗與共同失效構件清單，以獨立證據判別原因；只修補可見症狀將留下原本的傳力或滲流問題。","textEn":"A shared clamp failure defeats two barriers incorrectly treated as independent redundancy. Similar symptoms can arise from measurement bias: return to reconcile individual barrier tests with the inventory of shared failure components to discriminate the cause. Treating visible symptoms alone leaves the original transfer or seepage problem unresolved.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]},{"id":"b170-v14-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"]}],"quiz":{"question":"在「屏障獨立性與交接檔案」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Barrier independence and handover records\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援。","兩管節中心對準就代表周邊密封必定均勻接觸"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","A shared clamp failure defeats two barriers incorrectly treated as independent redundancy.","Aligned element centers guarantee uniform contact around the entire seal"],"answer":1,"explanation":"雙重密封共用的夾具失效，同時破壞被誤認為獨立的備援。 需以量測區分可能原因。","explanationEn":"A shared clamp failure defeats two barriers incorrectly treated as independent redundancy. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["b-src-underground","v14s-cedd-g4","v14s-femern","v14s-gina","v14s-omega"],"curriculumVersion":14,"stepCount":40,"estimatedMinutes":1000}};
